<script setup lang="ts">
import {computed,onMounted} from 'vue';
import {t} from '@kuaixie/i18n';
import {useProductPublishing,productImageId,type ProductImageFile} from '@kuaixie/ui/useProductPublishing';
import {api,uploadPrivateImage,downloadPrivateFile} from '../api/client';
import {uniEventValue} from '../utils/uniEvent';
const p=useProductPublishing(api);
const categoryName=computed(()=>{const row=p.categories.value.find(item=>String(item.id)===p.draft.value.categoryId);return row?p.categoryLabel(row):p.draft.value.categoryId?t('productMedia.currentCategory')+' '+p.draft.value.categoryId:t('productMedia.uncategorized')});
const categoryLabels=computed(()=>[t('productMedia.uncategorized'),...p.categories.value.map(p.categoryLabel)]);
function chooseCategory(event:unknown){const index=Number(uniEventValue(event));p.draft.value.categoryId=index>0?String(p.categories.value[index-1]?.id??''):''}
async function upload(){let preview='';await p.uploadImage(()=>uploadPrivateImage('product_image',{onSelected:path=>{preview=path},beforeUpload:p.sessionCurrent}),()=>preview)}
async function preview(path:string){if(!p.sessionCurrent())return;let source=p.imageSource(path);try{if(!source){const id=productImageId(path);if(!id)return;source=await downloadPrivateFile(id,'product_image');if(!p.sessionCurrent())return;p.setPreview(path,source)}uni.previewImage({urls:[source],fail:()=>{p.notice.value='productMedia.previewFailed'}})}catch{if(p.sessionCurrent())p.notice.value='productMedia.previewFailed'}}
function removeUnused(file:ProductImageFile){void p.deleteUnused(file,async()=>!!(await uni.showModal({title:t('productMedia.deleteUnused'),content:t('productMedia.confirmDelete')})).confirm)}
onMounted(()=>{void p.load();void p.loadCategories();void p.loadMedia()});
</script>
<template><view class="product-panel"><view class="title">{{$t('product.title')}}</view><text class="help">{{$t('product.help')}}</text><text>{{$t('product.name')}}</text><input v-model="p.draft.value.name" :disabled="p.busy.value" maxlength="255"/><text>{{$t('product.spec')}}</text><input v-model="p.draft.value.spec" :disabled="p.busy.value" maxlength="255"/><text>{{$t('product.region')}}</text><input v-model="p.draft.value.region" :disabled="p.busy.value" maxlength="64"/><text>{{$t('product.price')}}</text><input v-model="p.draft.value.price" :disabled="p.busy.value" type="digit"/><text>{{$t('product.stock')}}</text><input v-model="p.draft.value.stock" :disabled="p.busy.value" type="number"/><text>{{$t('product.note')}}</text><textarea v-model="p.draft.value.note" :disabled="p.busy.value" maxlength="1024"/>
<text>{{$t('productMedia.categorySearch')}}</text><input v-model="p.categorySearch.value" :disabled="p.busy.value" maxlength="100"/><button :disabled="p.busy.value||p.categoryLoading.value" @click="p.loadCategories(false)">{{$t('productMedia.search')}}</button><text>{{$t('productMedia.category')}}</text><picker :range="categoryLabels" :disabled="p.busy.value" @change="chooseCategory"><view class="category-choice">{{categoryName}} ⌄</view></picker><button v-if="p.moreCategories.value" :disabled="p.busy.value||p.categoryLoading.value" @click="p.loadCategories(true)">{{$t('productMedia.moreCategories')}}</button>
<button :disabled="p.busy.value||p.draft.value.imageUrls.length>=9" @click="upload">{{$t('productMedia.upload')}}</button><text class="help">{{$t('productMedia.imageHelp')}}</text><view class="image-grid"><view v-for="(path,index) in p.draft.value.imageUrls" :key="path" class="image-card"><image v-if="p.imageSource(path)" :src="p.imageSource(path)" mode="aspectFill" @click="preview(path)"/><text v-else class="help">{{$t('productMedia.previewPending')}} {{index+1}}</text><button :disabled="p.busy.value" @click="preview(path)">{{$t('productMedia.preview')}}</button><button :disabled="p.busy.value" @click="p.removeImage(path)">{{$t('productMedia.remove')}}</button></view></view><view class="item"><view>{{$t('productMedia.unusedLibrary')}}</view><button :disabled="p.busy.value||p.mediaLoading.value" @click="p.loadMedia()">{{$t('product.refresh')}}</button><view v-for="file in p.media.value.filter(row=>!row.consumed_at)" :key="file.id" class="image-card"><text>{{file.original_name||$t('productMedia.ownedImage')}}</text><image v-if="p.imageSource(file.publicPath)" :src="p.imageSource(file.publicPath)" mode="aspectFill" @click="preview(file.publicPath)"/><view class="actions"><button :disabled="p.busy.value" @click="preview(file.publicPath)">{{$t('productMedia.preview')}}</button><button :disabled="p.busy.value||p.draft.value.imageUrls.includes(file.publicPath)" @click="p.attachImage(file)">{{$t('productMedia.useImage')}}</button><button :disabled="p.busy.value||p.draft.value.imageUrls.includes(file.publicPath)" @click="removeUnused(file)">{{$t('productMedia.deleteUnused')}}</button></view></view></view>
<button :disabled="p.busy.value" @click="p.save">{{$t(p.editing.value?'product.saveEdit':'product.save')}}</button><button v-if="p.editing.value" :disabled="p.busy.value" @click="p.reset">{{$t('product.cancel')}}</button><view v-if="p.notice.value" class="help">{{$t(p.notice.value)}}</view><button :disabled="p.busy.value" @click="p.load(false)">{{$t('product.refresh')}}</button><view v-for="row in p.rows.value" :key="row.id" class="item"><view>{{row.name}}</view><text>{{row.price}} CNY · {{$t(row.status==='on'?'product.on':'product.off')}} · {{row.stock}}</text><view class="actions"><button :disabled="p.busy.value" @click="p.edit(row)">{{$t('product.edit')}}</button><button :disabled="p.busy.value" @click="p.toggle(row)">{{$t(row.status==='on'?'product.unlist':'product.list')}}</button></view></view><button v-if="p.more.value" :disabled="p.busy.value" @click="p.load(true)">{{$t('account.more')}}</button></view></template>
<style scoped>.product-panel{background:var(--kx-surface,#fff);padding:28rpx;border-radius:20rpx;margin:24rpx 0;display:flex;flex-direction:column;gap:16rpx}.title{font-size:32rpx;font-weight:700}.help{color:#64748b;font-size:24rpx;line-height:1.6}.product-panel input,.product-panel textarea,.category-choice{border:1rpx solid #cbd5e1;border-radius:12rpx;padding:16rpx;width:100%;box-sizing:border-box;font-size:27rpx}.product-panel button{background:#0e7490;color:#fff;font-size:26rpx;margin:0;padding:8rpx 22rpx}.product-panel button:disabled{opacity:.5}.item{padding:22rpx 0;border-top:1rpx solid #e2e8f0}.actions{display:flex;flex-wrap:wrap;gap:16rpx;margin-top:16rpx}.item text{color:#64748b;font-size:24rpx}.image-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16rpx}.image-card{padding:12rpx;border:1rpx solid #e2e8f0;border-radius:12rpx;display:flex;flex-direction:column;gap:12rpx}.image-card image{width:100%;height:200rpx}</style>
